// FILE: lib/features/planned_maintenance/domain/baf_knowledge_layer.dart

import 'dart:convert';

import 'module_composer_models.dart';

/// Deterministic embedded BAF Knowledge Layer v0.1.
///
/// In RC3 this is the static safety fallback behind the governed 5D stack:
/// Firestore knowledge_base -> Isar offline cache -> this embedded baseline.
/// Do not delete these rows; they are the first-time/bootstrap safety dataset.
class BafKnowledgeLayer {
  BafKnowledgeLayer._();

  static const String version = '0.1';
  static const String matrixVersion = 'bafKnowledge-v0.1.20260509';
  static const String sourceLabel = 'BAF Knowledge Matrix v0.1';
  static const String maintenanceManualRef = '7-1-13-0028-41-1012 / Maintenance Manual / Revision 0';
  static const String safetyOperationsManualRef = '7-1-13-0028-41-1011 / Safety and Operations Manual / Revision 0';
  static const String extractionPolicy = 'Static fallback safety baseline; cloud/cache rows override only through governed Admin/SI knowledge source.';

  static final Map<String, dynamic> matrix = _decodeMatrix();

  static final List<BafKnowledgeEntry> entries = _buildEntries();

  static final List<BafKnowledgeEntry> tagEntries = entries
      .where((entry) => entry.deviceTags.isNotEmpty || entry.resolverImpact == 'yes')
      .toList(growable: false);

  static final Map<String, List<BafKnowledgeEntry>> _tagIndex = _buildTagIndex(tagEntries);

  static int get knowledgeRowCount => entries.length;
  static int get tagRowCount => tagEntries.length;

  static Map<String, dynamic> metadataMap() => <String, dynamic>{
    'matrixVersion': matrixVersion,
    'sourceLabel': sourceLabel,
    'maintenanceManualRef': maintenanceManualRef,
    'safetyOperationsManualRef': safetyOperationsManualRef,
    'extractionPolicy': extractionPolicy,
    'knowledgeRowCount': knowledgeRowCount,
    'tagRowCount': tagRowCount,
  };

  static List<BafKnowledgeEntry> search(String query) {
    final key = query.trim().toLowerCase();
    if (key.isEmpty) return entries;
    return entries.where((entry) {
      final haystack = [
        entry.moduleCandidateCode,
        entry.taskText,
        entry.assetFamilyKey,
        entry.functionalSection,
        entry.componentGroup,
        entry.taskType,
        entry.frequency.name,
        entry.discipline.name,
        ...entry.ownerDisciplines,
        ...entry.safetyClasses,
        ...entry.procedureRefs,
        ...entry.partRefs,
        ...entry.deviceTags,
        entry.sourceLabel,
        entry.composerReadiness.name,
        entry.confidence.name,
      ].join(' ').toLowerCase();
      return haystack.contains(key);
    }).toList(growable: false);
  }

  static List<BafKnowledgeEntry> byTag(String normalizedTag) {
    final tag = normalizedTag.trim().toUpperCase();
    if (tag.isEmpty) return const <BafKnowledgeEntry>[];
    return _tagIndex[tag] ?? const <BafKnowledgeEntry>[];
  }

  static Map<String, List<BafKnowledgeEntry>> _buildTagIndex(
      List<BafKnowledgeEntry> sourceEntries,
      ) {
    final mutable = <String, List<BafKnowledgeEntry>>{};
    for (final entry in sourceEntries) {
      for (final rawTag in entry.deviceTags) {
        final tag = rawTag.trim().toUpperCase();
        if (tag.isEmpty) continue;
        mutable.putIfAbsent(tag, () => <BafKnowledgeEntry>[]).add(entry);
      }
    }
    return <String, List<BafKnowledgeEntry>>{
      for (final item in mutable.entries) item.key: List<BafKnowledgeEntry>.unmodifiable(item.value),
    };
  }

  static Map<String, dynamic> _decodeMatrix() {
    final decoded = jsonDecode(_matrixJson);
    if (decoded is Map) return Map<String, dynamic>.from(decoded);
    return <String, dynamic>{};
  }

  static List<BafKnowledgeEntry> _buildEntries() {
    final rawTasks = matrix['maintenanceTasks'];
    if (rawTasks is! List) return const <BafKnowledgeEntry>[];
    final entries = <BafKnowledgeEntry>[];
    for (var i = 0; i < rawTasks.length; i++) {
      final raw = rawTasks[i];
      if (raw is Map) {
        entries.add(BafKnowledgeEntry.fromMap(Map<String, dynamic>.from(raw), i));
      }
    }
    return entries;
  }
}

